#!/usr/bin/env python3
"""Render final recovery reports only from successful captured live verification. No connections."""
import json
from collections import Counter
from recovery import ROOT,WORK,load,required,atomic_save,sha
E=ROOT/'docs/evidence'
def main():
 r=load(E/'stage4c-execution-verification.json');required(r['status']=='passed' and r['migration_complete_within_approved_scope'],'No verified live completion')
 times=load(E/'stage4c-execution-times.json');a=load(WORK/'owner-authorization-archived.json');live=load(E/'stage4c-final-live-reconciliation.json');google=load(E/'stage4c-google-recovery-report.json')
 required(google['status']=='passed' and google['owner_private'],'Failure report not verified')
 m=load(WORK/'manifest.json');plan=load(ROOT/'work/etl/plan.json')
 records={x['values']['id']:x['values'] for unit in plan['units'] for x in unit if x['table']=='source_records'}
 outcomes=[]
 for item in plan['source_statuses']:
  v=records[item['source_record_id']];outcomes.append({**item,'planned_disposition':v['diagnostics']['planned_status'],'source_payload_retained':True,'live_execution_outcome':'preserved_and_source_status_verified','operational_acceptance':'pending_or_excluded_per_approved_scope'})
 required(len(outcomes)==len({x['source_record_id'] for x in outcomes})==20432,'Outcome coverage differs')
 required(Counter(x['database_status'] for x in outcomes)==r['source_states'],'Outcome statuses differ')
 atomic_save(WORK/'final-source-execution-outcomes.json',outcomes)
 (E/'stage4c-source-outcome-summary.json').write_text(json.dumps({'status':'passed','source_rows':20432,'unique_source_ids':20432,'source_states':dict(Counter(x['database_status'] for x in outcomes)),'row_level_outcomes_sha256':sha((WORK/'final-source-execution-outcomes.json').read_bytes()),'private_path':'Ignored work/stage4c/final-source-execution-outcomes.json','operational_acceptance':'pending or excluded; preservation success is not business approval'},indent=2)+'\n')
 counts=r['live_table_counts'];catalog=load(E/'stage4c-final-live-catalog.json');schemas={x['name']:x['schema'] for x in catalog['tables']}
 table='\n'.join('| '+schemas[k]+'.'+k+' | '+f'{v:,}'+' |' for k,v in sorted(counts.items(),key=lambda x:(schemas[x[0]],x[0])))
 (ROOT/'docs/34-recovery-execution-report.md').write_text(f'''# Stage 4C — Authorized recovery execution\n\n**Recovery succeeded within the approved sanitized preservation/pending-record scope.** All 179 remaining transactions are acknowledged and actual live PostgreSQL reconciliation passes. No original data transaction 0–39 was replayed. No schema, permissions, memberships, OAuth or frontend change occurred.\n\n## Authorization and target\n\nExact destination: kc2-integrated-data-system / `hmlbdozsqxlwzvjimjwh`, Tokyo `ap-northeast-1`, PostgreSQL 17.11. The owner designates this a non-production internal pilot and explicitly retains Tokyo as the exception to Mumbai.\n\nOwner approval: conversation message “Goalkeep KC-2 — Stage 4C: Authorized Migration Recovery Execution”. Approval first observed by the clock tool at **{a['issued_at']}**, expires **{a['expires_at']}**; four hours, never extended. The protected artifact binds destination, all four approved hashes, source scope, owner reference and window. Adapter started {times['started_at']}; completed {times['finished_at']}, within that window. The authorization is now archived/inactive; credentials and the full journal remain private.\n\nRecovery manifest: `{r['recovery_manifest_sha256']}`. Original plan: `{m['original_plan_sha256']}`. Original execution manifest: `{m['original_execution_manifest_sha256']}`. Recovery planning: `{m['recovery_planning_sha256']}`.\n\nBefore writing, fresh MCP checks verified project/name/region/version, all 19 tables and complete schema/security, ledger, no active import, exact 12-artifact/9,988-staged-row prefix and immutable metadata. Source hashes, all packets/SQL, 40 receipts, code and expiry matched; the failure destination was owner-private. The original initial-load guard was not bypassed.\n\n## Actual execution\n\nExecuted original data indices 40–136 (97 transactions), then source-status 0–81 (82). All **179/179** received validated commit receipts; **zero failed or uncertain requests** and zero retries. Earlier 40 commits are preserved, accounting for all 219 original transactions. Additional direct inserts: **{r['additional_direct_inserts']:,}**. Final direct rows: **{r['final_direct_rows']:,}**. Generated audit rows: **{r['final_audit_rows']:,}**. Source updates: **{r['source_updates']:,}**. These are verified live results, separate from earlier local simulations.\n\nThe reviewed immutable loader/SQL, deterministic IDs, transaction boundaries, compressed SHA-verified packets, constraints and audit triggers were used unchanged. The private hash-chained/fsynced journal binds all request IDs and receipts; SHA-256 `{r['journal_sha256']}`. No recovery failure required a further approval or corrective database write.\n\nA local reconciliation reader initially retained the MCP `reconciliation` result-column wrapper. Unwrapping that captured result fixed the verification-reader mismatch; the checks then passed without another SQL execution or any data change. This was not a database transaction failure.\n\nEvidence: [execution verification](evidence/stage4c-execution-verification.json), [times](evidence/stage4c-execution-times.json), [live reconciliation](evidence/stage4c-final-live-reconciliation.json), [live security](evidence/stage4c-final-live-security.json), [catalog](evidence/stage4c-final-live-catalog.json), [failure-report receipt](evidence/stage4c-google-recovery-report.json).\n\nAll original source rows remain accounted for, but operational/business approval is not complete. See [reconciliation](35-final-migration-reconciliation.md) and [data-quality follow-up](36-post-migration-data-quality.md). Stop here for Phase 1 Final QA; PR #1 remains draft/unmerged.\n''')
 (ROOT/'docs/35-final-migration-reconciliation.md').write_text(f'''# Stage 4C — Final live migration reconciliation\n\n**Actual live verification passed.** This report supersedes earlier interrupted counts for current state while preserving those historical reports. Exact project `hmlbdozsqxlwzvjimjwh`, Tokyo pilot.\n\n## Actual table inventory\n\n| Schema.table | Live rows |\n| --- | ---: |\n{table}\n\nDirect rows total **{r['final_direct_rows']:,}**, excluding **{r['final_audit_rows']:,}** trigger-generated history rows. No manually inserted audit rows, memberships, attendance, ADL or support facts exist. All imported operational projections remain pending, references inactive, dates NULL and identity candidates unapproved.\n\n## Source and audit reconciliation\n\nAll **20,432** source rows have one final status: resolved **1,194**, reference_only **15,301**, blocked **3,937**. Planned dispositions remain distinct: transformed **1,194**, source-only **15,301**, identity-pending **3,623**, business-pending **314**. Blocked combines the last two; it is not a data-loss count. The complete protected row-level outcome ledger is `work/stage4c/final-source-execution-outcomes.json`, outside Git.\n\nThe source-coordinate digest and every table key/payload/status digest equal the approved plan/reference. No duplicate source coordinates or IDs, silent loss, missing provenance or invalid questionnaire/child-caregiver links were found. **99 modeled FK checks have zero violations.** Literal source-to-target child/caregiver identifiers and canonical names reconcile; questionnaire name disagreements stay source evidence.\n\nAudit history totals **28,293**: the exact planned per-table INSERT history plus **20,432 source-record UPDATE events**. Audit before/after content, operation/key uniqueness, backend actor attribution and original status transitions reconcile. Existing 9,988 rows changed only as permitted: approved source-state and mutable audit fields. Their IDs, original payloads, coordinates, diagnostics and creation metadata, and all 12 complete artifact rows, match the pre-execution immutable anchor.\n\nFull live source/FK checks: [aggregate evidence](evidence/stage4c-final-live-reconciliation.json). Final full payload checkpoint: [digests](evidence/stage4c-final-live-checkpoint.json). Existing prefix preservation: [anchor](evidence/stage4c-final-live-anchor.json). Counts and transaction receipts: [verification](evidence/stage4c-execution-verification.json).\n\n## Security and architecture\n\nNo differences from the approved complete catalog: 19 tables, 334 columns, 221 constraints, 72 indexes, 81 user triggers, 40 policies and 15 functions. The existing three migration ledger entries are unchanged. RLS and effective table/function privileges equal the deployed reference. Anonymous reads are denied; an unapproved authenticated SQL session sees zero rows in 18 selectable tables, now including populated registries/profiles/source/audit evidence. Memberships and access-role definitions remain zero. No security policy was weakened to load data. These are live SQL-role checks, not Google OAuth/PostgREST end-to-end validation.\n\nAll 179 recovery batches and the earlier 40 are accounted for. Stage 4B is complete **within the authorized preservation/pending-record scope**, not a claim that all NGO observations are ready for analytics or user access.\n''')
 (ROOT/'docs/36-post-migration-data-quality.md').write_text('''# Stage 4C — Post-migration data quality and follow-up\n\nThe approved sanitized preservation/pending-record migration is complete; business and analytical acceptance remain pending. No data-quality problem was silently repaired to make execution pass. There were zero new failed/uncertain recovery transactions and zero unsupported automatic value recoveries.\n\n## Preserved exceptions\n\n- 60 questionnaire source-name disagreements remain evidence. The 106 questionnaire relationships follow exact verified child/caregiver IDs and do not overwrite canonical master names. There are 86 missing numeric answer slots; no unapproved score was calculated.\n- The 2,089 identity candidates remain unapproved. Name-only attendance matches are not accepted; operational attendance remains empty. Source date-header problems (610 marks without recognized dates, four malformed headers and seven calendar mismatches) remain unresolved.\n- Four missing dates among 194 investigated ADL visit slots remain missing. No operational ADL visits or support observations were created. Three birth/joining chronology conflicts and sanitized date-fidelity limitations remain open.\n- 128 source-reported programme slots remain pending with NULL dates, not approved chronological programme events. Source-scoped reference values are inactive; category/dropdown meanings, questionnaire scale/formula, parent crosswalks and event grain need separate business decisions.\n- Source states describe processing, not acceptance: 3,623 identity-pending and 314 business-pending rows are retained with original lineage. Source-only rows include summaries, repeated views and unsupported fields; they were preserved, not discarded or treated as operational observations.\n\n## Interruption history and failure report\n\nThe previous 40-commit interruption remains in docs 28–30 and its original private journals. Actual Stage 4C outcomes now supersede that stopped state. The existing owner-private Google report preserves every preparation entry and historical interruption description, marks the transport interruption recovered and adds one verified completion summary per source. No source personal values or credentials are added and sharing remains private. The report receipt is [recorded here](evidence/stage4c-google-recovery-report.json); preparation findings stay distinct from execution failures.\n\n## Next approval gates\n\nProceed only to separately requested Phase 1 Final QA/acceptance: review pending projections and source-quality decisions, sanitized date policy, analytical readiness, retention/privacy and PM handover. Google Docs project-context synchronization destination remains unresolved. Admin/Member permissions, private access, Google OAuth/HTTP testing, frontend/Phase 2, any schema change and merging PR #1 remain outside this execution authorization. No additional database write or value invention is authorized by completing this import.\n''')
 print(json.dumps({'reports':[34,35,36],'outcomes':len(outcomes),'status':'rendered_from_verified_live_evidence'}))
if __name__=='__main__':main()
